arguments.command:
cd /workspace && python3 - <<'PYEOF'
# restore the clean validator and re-apply the inline address fix
p='src/image.cpp'
s=open('/tmp/image.cpp.bak').read()
old = """            uint64_t bits = rel == 0 ? 0 : (fragment >> (64 - rel));
            FEntry entry;
            entry.len = static_cast<uint8_t>(length);
            entry.hop = hop;
            if (origin + rel <= 64) {
                entry.hi = bits << (64 - origin - rel);
                entry.lo = 0;
            } else {
                entry.hi = 0;
                entry.lo = bits << (64 - (origin + rel - 64));
            }"""
new = """            uint64_t bits = rel == 0 ? 0 : (fragment >> (64 - rel));
            FEntry entry;
            entry.len = static_cast<uint8_t>(length);
            entry.hop = hop;
            // The address keeps the region bits before the forest origin and
            // takes the prefix bits from the inline fragment.
            entry.hi = reg_hi;
            entry.lo = reg_lo;
            mask128(entry.hi, entry.lo, origin + rel);
            set_bits(entry.hi, entry.lo, origin, bits, rel);"""
assert old in s
s = s.replace(old, new)
s = s.replace("""inline bool same_prefix(""","""inline void mask128(uint64_t& hi, uint64_t& lo, int len) {
    if (len <= 0) {
        hi = 0;
        lo = 0;
    } else if (len < 64) {
        hi = apply_mask(hi, len);
        lo = 0;
    } else if (len == 64) {
        lo = 0;
    } else {
        lo = apply_mask(lo, len - 64);
    }
}

inline bool same_prefix(""")
open(p,'w').write(s)
PYEOF
grep -c "getenv" src/image.cpp; python3 build.py 2>&1|tail -2 && python3 /tmp/runex.py
